mapper.select:
select t.machine_id,t.machine_id machineId,t.open_model,t.open_model openModel,t.name,t.person_id,t.person_id
personId,t.start_time,t.start_time startTime,t.status_cd,t.status_cd statusCd,t.end_time,t.end_time
endTime,t.state,t.community_id,t.community_id communityId,t.lp_id,t.lp_id lpId,t.card_number,t.card_number
cardNumber,t.create_time createTime,lm.machine_name machineName,lm.machine_code machineCode,bo.link tel
from lock_person t
left join lock_machine lm on t.machine_id = lm.machine_id  and lm.status_cd = '0'
left join building_owner bo on t.person_id = bo.member_id and bo.status_cd = '0'
where 1 =1

    and t.machine_id= #{machineId}


    and t.open_model= #{openModel}


    and t.name= #{name}


    and t.person_id= #{personId}


    and t.start_time= #{startTime}


    and t.start_time <= #{queryTime}
    and t.end_time >= #{queryTime}


    and t.status_cd= #{statusCd}


    and t.end_time= #{endTime}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and lm.room_id= #{roomId}


    and t.lp_id= #{lpId}


    and t.card_number= #{cardNumber}


    and lm.machine_name like concat('%', #{machineName}, '%')


    and lm.machine_code like concat('%', #{machineCode}, '%')

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update lock_person t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.machine_id= #{machineId}


    , t.open_model= #{openModel}


    , t.name= #{name}


    , t.person_id= #{personId}


    , t.start_time= #{startTime}


    , t.end_time= #{endTime}


    , t.state= #{state}


    , t.community_id= #{communityId}


    , t.card_number= #{cardNumber}

where 1=1

    and t.lp_id= #{lpId}

